globalThis.process ??= {}; globalThis.process.env ??= {};
import { c as createComponent, r as renderComponent, a as renderTemplate, u as unescapeHTML } from '../../chunks/astro/server_BA1YRW7y.mjs';
import { $ as $$BlogPost } from '../../chunks/BlogPost_DrskGsOj.mjs';
export { r as renderers } from '../../chunks/_@astro-renderers_CIWobTvY.mjs';

const html = () => "<h2 id=\"introduction\">Introduction</h2>\n<p>Laravel is a magnificent framework for building web applications, but its dynamic nature introduces unique SEO challenges. Unlike a static HTML site where every URL maps to a fixed file, a Laravel application generates pages on the fly — rendering Blade views, querying databases, and resolving routes at runtime. Search engines need clear signals to understand and rank this content.</p>\n<p>The goal of this article is simple: <strong>give you a battle-tested toolkit for Laravel SEO</strong>. We’ll look at what Laravel gives you out of the box, survey the best community packages (with real code examples), and show you how to let non-technical team members manage meta tags without touching a line of code.</p>\n<hr>\n<h2 id=\"1-laravels-native-seo-helpers\">1. Laravel’s Native SEO Helpers</h2>\n<p>Before reaching for a package, it’s worth knowing what Laravel already does well.</p>\n<h3 id=\"clean-urls-with-route-naming\">Clean URLs with Route Naming</h3>\n<p>Laravel’s routing system lets you define semantic URLs that search engines love:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Instead of /posts?category=seo&#x26;id=42</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">Route</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">resource</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'posts'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">PostController</span><span style=\"color:#F97583\">::class</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Generates: /posts, /posts/{post}, /posts/{post}/edit</span></span></code></pre>\n<p>Use <code>Route::name()</code> and named routes to generate consistent URLs throughout your app — this avoids duplicate content from multiple URL patterns pointing to the same page.</p>\n<h3 id=\"dynamic-title-tags-with-blade-sections\">Dynamic Title Tags with Blade Sections</h3>\n<p>Blade’s section inheritance is a simple yet effective SEO tool:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"blade\"><code><span class=\"line\"><span style=\"color:#6A737D\">&#x3C;!-- layouts/app.blade.php --></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">title</span><span style=\"color:#E1E4E8\">></span><span style=\"color:#F97583\">@yield</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'title'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#B392F0\">config</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'app.name'</span><span style=\"color:#E1E4E8\">))&#x3C;/</span><span style=\"color:#85E89D\">title</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">&#x3C;!-- posts/show.blade.php --></span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@extends</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'layouts.app'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@section</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'title'</span><span style=\"color:#E1E4E8\">, $post</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">title </span><span style=\"color:#F97583\">.</span><span style=\"color:#9ECBFF\"> ' — My Blog'</span><span style=\"color:#E1E4E8\">)</span></span></code></pre>\n<h3 id=\"caching-for-speed\">Caching for Speed</h3>\n<p>Page speed is a confirmed ranking factor. Laravel’s caching layer is your first line of defense:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Cache an entire response for anonymous visitors</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> Illuminate\\Support\\Facades\\Cache</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">$posts </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> Cache</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">remember</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'posts.index'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">3600</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#F97583\">fn</span><span style=\"color:#E1E4E8\"> () =></span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    Post</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">with</span><span style=\"color:#E1E4E8\">([</span><span style=\"color:#9ECBFF\">'author'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'tags'</span><span style=\"color:#E1E4E8\">])</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">published</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Or use spatie/laravel-responsecache for full-page caching</span></span></code></pre>\n<h3 id=\"robotstxt-and-sitemaps\">robots.txt and Sitemaps</h3>\n<p>Serve a dynamic <code>robots.txt</code> directly from a route:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#79B8FF\">Route</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'robots.txt'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#F97583\">function</span><span style=\"color:#E1E4E8\"> () {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    $content </span><span style=\"color:#F97583\">=</span><span style=\"color:#9ECBFF\"> \"User-agent: *</span><span style=\"color:#79B8FF\">\\n</span><span style=\"color:#9ECBFF\">Allow: /</span><span style=\"color:#79B8FF\">\\n</span><span style=\"color:#9ECBFF\">Sitemap: \"</span><span style=\"color:#F97583\"> .</span><span style=\"color:#B392F0\"> url</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'sitemap.xml'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#B392F0\"> response</span><span style=\"color:#E1E4E8\">($content)</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">header</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Content-Type'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'text/plain'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span></code></pre>\n<p>For sitemaps, the <a href=\"https://github.com/spatie/laravel-sitemap\">spatie/laravel-sitemap</a> package is the de facto standard — it generates XML sitemaps from your models and routes with a single Artisan command.</p>\n<hr>\n<h2 id=\"2-top-seo-packages-for-laravel-2025-update\">2. Top SEO Packages for Laravel (2025 Update)</h2>\n<p>The Laravel community has produced several excellent SEO packages. Here is how they compare:</p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<table><thead><tr><th>Package</th><th>Stars</th><th>Maintenance</th><th>Key Feature</th><th>Install Difficulty</th></tr></thead><tbody><tr><td><a href=\"https://github.com/ralphjsmit/laravel-seo\">ralphjsmit/laravel-seo</a></td><td>~850</td><td>Active (v1.8.1, Mar 2026)</td><td>Model-based SEO with <code>HasSEO</code> trait</td><td>Easy</td></tr><tr><td><a href=\"https://github.com/artesaos/seotools\">artesaos/seotools</a></td><td>~3.3k</td><td>Maintained (v1.4.0, Mar 2026)</td><td>Multiple facades (SEOMeta, OpenGraph, TwitterCard, JsonLd)</td><td>Easy</td></tr><tr><td><a href=\"https://github.com/romanzipp/laravel-seo\">romanzipp/laravel-seo</a></td><td>~352</td><td>Maintained (v2.6.0, Oct 2023)</td><td>Laravel Mix asset preloading, maximum customization</td><td>Medium</td></tr><tr><td><a href=\"https://packagist.org/packages/elegantly/laravel-seo\">elegantly/laravel-seo</a></td><td>~12</td><td>Active (v1.4.0, Apr 2026)</td><td>Flexible tag management, fluent API</td><td>Easy</td></tr><tr><td><a href=\"https://github.com/butschster/LaravelMetaTags\">butschster/LaravelMetaTags</a></td><td>~630</td><td>Active</td><td>Framework-agnostic meta tags, Inertia support</td><td>Medium</td></tr></tbody></table>\n<h3 id=\"ralphjsmitlaravel-seo-recommended\">ralphjsmit/laravel-seo (Recommended)</h3>\n<p>This package, featured on <a href=\"https://laravel-news.com/laravel-seo\">Laravel News in August 2024</a>, takes a unique approach: it attaches SEO data directly to your Eloquent models. If you are familiar with Spatie’s Media Library, the pattern will feel right at home.</p>\n<p><strong>Installation:</strong></p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"bash\"><code><span class=\"line\"><span style=\"color:#B392F0\">composer</span><span style=\"color:#9ECBFF\"> require</span><span style=\"color:#9ECBFF\"> ralphjsmit/laravel-seo</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">php</span><span style=\"color:#9ECBFF\"> artisan</span><span style=\"color:#9ECBFF\"> vendor:publish</span><span style=\"color:#79B8FF\"> --tag=</span><span style=\"color:#9ECBFF\">\"seo-migrations\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">php</span><span style=\"color:#9ECBFF\"> artisan</span><span style=\"color:#9ECBFF\"> vendor:publish</span><span style=\"color:#79B8FF\"> --tag=</span><span style=\"color:#9ECBFF\">\"seo-config\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">php</span><span style=\"color:#9ECBFF\"> artisan</span><span style=\"color:#9ECBFF\"> migrate</span></span></code></pre>\n<p><strong>Basic usage — render sensible defaults immediately:</strong></p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"blade\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">head</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    {!!</span><span style=\"color:#B392F0\"> seo</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#79B8FF\">!!}</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">head</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<p>That single line outputs a <code>&#x3C;title></code> tag, meta description, Open Graph tags, Twitter Cards, canonical URL, and robots meta — all with sensible defaults from <code>config/seo.php</code>.</p>\n<p><strong>Model-based SEO — the real power:</strong></p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> RalphJSmit\\Laravel\\SEO\\Support\\HasSEO</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> Post</span><span style=\"color:#F97583\"> extends</span><span style=\"color:#B392F0\"> Model</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    use</span><span style=\"color:#79B8FF\"> HasSEO</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<p>This creates a one-to-one <code>seo</code> relationship automatically. You can update SEO data like this:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">$post </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> Post</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">find</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">$post</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">seo</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">([</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'title'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'My Great Post'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'description'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'A compelling description for search results.'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'image'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'images/posts/1.jpg'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">]);</span></span></code></pre>\n<p>But the killer feature is <code>getDynamicSEOData()</code>, which lets you pull SEO values directly from your model’s existing fields without any duplication:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> RalphJSmit\\Laravel\\SEO\\Support\\SEOData</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> Post</span><span style=\"color:#F97583\"> extends</span><span style=\"color:#B392F0\"> Model</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    use</span><span style=\"color:#79B8FF\"> HasSEO</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">    public</span><span style=\"color:#F97583\"> function</span><span style=\"color:#B392F0\"> getDynamicSEOData</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> SEOData</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#F97583\"> new</span><span style=\"color:#79B8FF\"> SEOData</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            title</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">title,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            description</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">str</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">body)</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">limit</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">160</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            image</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">featured_image,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            author</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">author</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">name,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            published_time</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">created_at,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<p>Now <code>{!! seo()->for($post) !!}</code> in your Blade view automatically pulls live data from the model. The resolution order is: <code>getDynamicSEOData()</code> > associated SEO model > config defaults — so the most specific value wins.</p>\n<p>The package also supports structured data via <code>SchemaCollection</code>:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> RalphJSmit\\Laravel\\SEO\\SchemaCollection</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">public</span><span style=\"color:#F97583\"> function</span><span style=\"color:#B392F0\"> getDynamicSEOData</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> SEOData</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#F97583\"> new</span><span style=\"color:#79B8FF\"> SEOData</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        title</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">title,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        schema</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">SchemaCollection</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">make</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">            -></span><span style=\"color:#B392F0\">addArticle</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">            -></span><span style=\"color:#B392F0\">addBreadcrumbs</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">function</span><span style=\"color:#E1E4E8\"> ($breadcrumbs) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">                return</span><span style=\"color:#E1E4E8\"> $breadcrumbs</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">prependBreadcrumbs</span><span style=\"color:#E1E4E8\">([</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">                    'Home'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#B392F0\"> url</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/'</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">                    'Blog'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#B392F0\"> url</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/blog'</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">                ]);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">            }),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<h3 id=\"artesaosseotools-the-veteran\">Artesaos/seotools (The Veteran)</h3>\n<p>With over 3,300 stars, <a href=\"https://github.com/artesaos/seotools\">artesaos/seotools</a> is the oldest and most widely known Laravel SEO package. It was the go-to solution for years and is still maintained (latest v1.4.0 supports Laravel 13). However, it shows its age in a few ways:</p>\n<ul>\n<li>Requires calling separate facades (<code>SEOMeta</code>, <code>OpenGraph</code>, <code>TwitterCard</code>, <code>JsonLd</code>) for each tag type</li>\n<li>No built-in model binding — you manually set tags in every controller method</li>\n<li>No automatic tag generation — you must explicitly call <code>SEOMeta::setTitle()</code>, etc.</li>\n</ul>\n<p>Where it still shines is its comprehensive Open Graph support — it handles every OG namespace (article, book, profile, music, video, place) with dedicated methods like <code>setArticle()</code>, <code>setProfile()</code>, etc. If you need fine-grained OG control, it is unmatched.</p>\n<p><strong>Why newer packages are replacing it:</strong> the “set everything manually in the controller” approach creates duplication and makes it hard for non-developers to manage SEO. Modern packages like ralphjsmit/laravel-seo automate this by binding SEO data to models.</p>\n<h3 id=\"romanzipplaravel-seo-customization--mix\">Romanzipp/laravel-seo (Customization + Mix)</h3>\n<p><a href=\"https://github.com/romanzipp/laravel-seo\">Romanzipp/laravel-seo</a> takes a different approach — it is a low-level, maximum-flexibility SEO toolkit. Instead of model binding, you build your SEO tag collection programmatically.</p>\n<p>Its standout feature is <strong>Laravel Mix integration</strong>: it can automatically preload all generated frontend assets via the Mix manifest:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#B392F0\">seo</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">mix</span><span style=\"color:#E1E4E8\">();</span></span></code></pre>\n<p>This reads your <code>mix-manifest.json</code> and adds preload/prefetch links for CSS and JS assets — a significant performance and SEO boost.</p>\n<p>It also offers a hook system for modifying tags at runtime and a section system for organizing tags by page region.</p>\n<h3 id=\"elegantlylaravel-seo-modern-fluent-api\">Elegantly/laravel-seo (Modern Fluent API)</h3>\n<p><a href=\"https://packagist.org/packages/elegantly/laravel-seo\">Elegantly/laravel-seo</a> is a newer entrant with a clean, fluent API. It handles standard HTML tags, Open Graph, Twitter Cards, JSON-LD structured data, and localization alternates:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#B392F0\">seo</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">setTitle</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Homepage'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">setDescription</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'The homepage description'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">setImage</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">asset</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'images/og.jpg'</span><span style=\"color:#E1E4E8\">))</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">setLocale</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'fr'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">setAlternates</span><span style=\"color:#E1E4E8\">([</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        new</span><span style=\"color:#79B8FF\"> Alternate</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">hreflang</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'en'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#B392F0\">href</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">route</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'home'</span><span style=\"color:#E1E4E8\">, [</span><span style=\"color:#9ECBFF\">'locale'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'en'</span><span style=\"color:#E1E4E8\">])),</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        new</span><span style=\"color:#79B8FF\"> Alternate</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">hreflang</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'fr'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#B392F0\">href</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#B392F0\">route</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'home'</span><span style=\"color:#E1E4E8\">, [</span><span style=\"color:#9ECBFF\">'locale'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'fr'</span><span style=\"color:#E1E4E8\">])),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ])</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">when</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">!</span><span style=\"color:#79B8FF\">App</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">isProduction</span><span style=\"color:#E1E4E8\">(), </span><span style=\"color:#F97583\">fn</span><span style=\"color:#E1E4E8\">($seo) => $seo</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">noIndex</span><span style=\"color:#E1E4E8\">());</span></span></code></pre>\n<p>It is lightweight, well-tested with Pest, and supports Laravel 11/12/13.</p>\n<hr>\n<h2 id=\"3-practical-implementation-adding-meta-tags-to-a-blog-post\">3. Practical Implementation: Adding Meta Tags to a Blog Post</h2>\n<p>Let’s walk through a real example: adding full SEO metadata to a blog post, using the ralphjsmit/laravel-seo package.</p>\n<h3 id=\"step-1-prepare-your-model\">Step 1: Prepare Your Model</h3>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> RalphJSmit\\Laravel\\SEO\\Support\\HasSEO</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> RalphJSmit\\Laravel\\SEO\\Support\\SEOData</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> Post</span><span style=\"color:#F97583\"> extends</span><span style=\"color:#B392F0\"> Model</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    use</span><span style=\"color:#79B8FF\"> HasSEO</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">    protected</span><span style=\"color:#E1E4E8\"> $fillable </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> [</span><span style=\"color:#9ECBFF\">'title'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'slug'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'body'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'excerpt'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'featured_image'</span><span style=\"color:#E1E4E8\">];</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">    public</span><span style=\"color:#F97583\"> function</span><span style=\"color:#B392F0\"> getDynamicSEOData</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> SEOData</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#F97583\"> new</span><span style=\"color:#79B8FF\"> SEOData</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            title</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">title,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            description</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">excerpt </span><span style=\"color:#F97583\">??</span><span style=\"color:#B392F0\"> str</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">body)</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">limit</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">160</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            image</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">featured_image,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            author</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">author</span><span style=\"color:#F97583\">?-></span><span style=\"color:#E1E4E8\">name,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            published_time</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">created_at,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            modified_time</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">updated_at,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            section</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">category</span><span style=\"color:#F97583\">?-></span><span style=\"color:#E1E4E8\">name,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            tags</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">tags</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">pluck</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'name'</span><span style=\"color:#E1E4E8\">)</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">toArray</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">            schema</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">SchemaCollection</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">make</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">addArticle</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<h3 id=\"step-2-configure-defaults\">Step 2: Configure Defaults</h3>\n<p>In <code>config/seo.php</code>, set your site-wide fallbacks:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">return</span><span style=\"color:#E1E4E8\"> [</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'site_name'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'My Laravel Blog'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'title'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> [</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        'suffix'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> ' — My Laravel Blog'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        'infer_title_from_url'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#79B8FF\"> true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ],</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'description'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> [</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        'fallback'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'A great Laravel blog about web development.'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ],</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'image'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> [</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        'fallback'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'images/default-og.png'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ],</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'canonical_link'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#79B8FF\"> true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'twitter'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> [</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        '@username'</span><span style=\"color:#F97583\"> =></span><span style=\"color:#9ECBFF\"> 'mytwitterhandle'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">];</span></span></code></pre>\n<h3 id=\"step-3-render-in-your-blade-layout\">Step 3: Render in Your Blade Layout</h3>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"blade\"><code><span class=\"line\"><span style=\"color:#6A737D\">&#x3C;!-- layouts/app.blade.php --></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;!</span><span style=\"color:#85E89D\">DOCTYPE</span><span style=\"color:#B392F0\"> html</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">html</span><span style=\"color:#B392F0\"> lang</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"en\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">head</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> charset</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"UTF-8\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"viewport\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"width=device-width, initial-scale=1.0\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    {!!</span><span style=\"color:#B392F0\"> seo</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#79B8FF\">!!}</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">    &#x3C;!-- seo() already renders &#x3C;title>, meta tags, OG, Twitter, canonical --></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">head</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"blade\"><code><span class=\"line\"><span style=\"color:#6A737D\">&#x3C;!-- posts/show.blade.php --></span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@extends</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'layouts.app'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@section</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'content'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    {!!</span><span style=\"color:#B392F0\"> seo</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">for</span><span style=\"color:#E1E4E8\">($post) </span><span style=\"color:#79B8FF\">!!}</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">    &#x3C;!-- rest of the page --></span></span>\n<span class=\"line\"><span style=\"color:#F97583\">@endsection</span></span></code></pre>\n<h3 id=\"step-4-the-generated-html\">Step 4: The Generated HTML</h3>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"html\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">title</span><span style=\"color:#E1E4E8\">>My Great Post — My Laravel Blog&#x3C;/</span><span style=\"color:#85E89D\">title</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"description\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"A compelling description for search results.\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"robots\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"max-snippet:-1,max-image-preview:large,max-video-preview:-1\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">link</span><span style=\"color:#B392F0\"> rel</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"canonical\"</span><span style=\"color:#B392F0\"> href</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"https://example.com/posts/my-great-post\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"og:title\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"My Great Post\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"og:description\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"A compelling description for search results.\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"og:image\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"https://example.com/storage/images/posts/1.jpg\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"og:url\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"https://example.com/posts/my-great-post\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"og:type\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"article\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"og:site_name\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"My Laravel Blog\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"article:published_time\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"2025-05-13T10:00:00+00:00\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"article:author\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Jane Doe\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"article:section\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Laravel\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> property</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"article:tag\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"SEO\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"twitter:card\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"summary_large_image\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"twitter:title\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"My Great Post\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"twitter:description\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"A compelling description for search results.\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"twitter:image\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"https://example.com/storage/images/posts/1.jpg\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">script</span><span style=\"color:#B392F0\"> type</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"application/ld+json\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    \"@context\": \"https://schema.org\",</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    \"@type\": \"Article\",</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    \"headline\": \"My Great Post\",</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    \"description\": \"A compelling description for search results.\",</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    \"image\": \"https://example.com/storage/images/posts/1.jpg\",</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    \"author\": {\"@type\": \"Person\", \"name\": \"Jane Doe\"},</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    \"datePublished\": \"2025-05-13T10:00:00+00:00\",</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    \"dateModified\": \"2025-05-13T10:00:00+00:00\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">script</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<p>All of that from a single <code>{!! seo()->for($post) !!}</code> call — no manual tag wrangling.</p>\n<hr>\n<h2 id=\"4-letting-non-developers-manage-seo\">4. Letting Non-Developers Manage SEO</h2>\n<p>One of the most common questions on Laracasts and Reddit is: <em>“How do I let my SEO specialist edit meta tags without giving them access to the codebase?”</em></p>\n<p>The answer is a simple admin panel. Since the <code>ralphjsmit/laravel-seo</code> package stores SEO data in a <code>seo</code> database table with a polymorphic relationship, you can expose it through any admin panel — Filament, Nova, or a custom CRUD.</p>\n<h3 id=\"filament-integration\">Filament Integration</h3>\n<p>There is a dedicated companion package: <a href=\"https://github.com/ralphjsmit/laravel-filament-seo\">ralphjsmit/laravel-filament-seo</a>. It provides a ready-made Filament component:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> RalphJSmit\\Filament\\SEO\\SEO</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">public</span><span style=\"color:#F97583\"> static</span><span style=\"color:#F97583\"> function</span><span style=\"color:#B392F0\"> form</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">Form</span><span style=\"color:#E1E4E8\"> $form)</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> Form</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> $form</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">schema</span><span style=\"color:#E1E4E8\">([</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        SEO</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">make</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">        // Your other fields...</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ]);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<p>This renders a card with title, author, description, and image fields that automatically save to the <code>seo</code> relationship. No additional wiring needed.</p>\n<h3 id=\"custom-admin-panel-trait-approach\">Custom Admin Panel (Trait Approach)</h3>\n<p>If you are not using Filament, you can create a reusable trait for any model:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">trait</span><span style=\"color:#B392F0\"> HasSeoAdmin</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    public</span><span style=\"color:#F97583\"> static</span><span style=\"color:#F97583\"> function</span><span style=\"color:#B392F0\"> bootHasSeoAdmin</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">:</span><span style=\"color:#F97583\"> void</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        static::</span><span style=\"color:#B392F0\">saved</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">function</span><span style=\"color:#E1E4E8\"> ($model) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">            if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#B392F0\">request</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">has</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'seo'</span><span style=\"color:#E1E4E8\">)) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">                $model</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">seo</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">request</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">input</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'seo'</span><span style=\"color:#E1E4E8\">));</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">            }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<p>Then in your admin form, simply add the SEO fields:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"blade\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">input</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"seo[title]\"</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"</span><span style=\"color:#79B8FF\">{{</span><span style=\"color:#E1E4E8\"> $post</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">seo</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">title</span><span style=\"color:#79B8FF\"> }}</span><span style=\"color:#9ECBFF\">\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">textarea</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"seo[description]\"</span><span style=\"color:#E1E4E8\">></span><span style=\"color:#79B8FF\">{{</span><span style=\"color:#E1E4E8\"> $post</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">seo</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">description </span><span style=\"color:#79B8FF\">}}</span><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">textarea</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">input</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"seo[image]\"</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"</span><span style=\"color:#79B8FF\">{{</span><span style=\"color:#E1E4E8\"> $post</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">seo</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">image</span><span style=\"color:#79B8FF\"> }}</span><span style=\"color:#9ECBFF\">\"</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<h3 id=\"the-trait-for-every-model\">The Trait for Every Model</h3>\n<p>The true power of model-based SEO is that you can attach it to any model — not just blog posts, but also products, categories, landing pages, and even your homepage. With ralphjsmit/laravel-seo, every model that uses the <code>HasSEO</code> trait automatically gets:</p>\n<ol>\n<li>A <code>seo</code> relationship</li>\n<li>A pre-created SEO model on creation</li>\n<li>The ability to override via <code>getDynamicSEOData()</code></li>\n<li>Admin-editable fields if you expose them in your panel</li>\n</ol>\n<hr>\n<h2 id=\"5-structured-data--json-ld\">5. Structured Data &#x26; JSON-LD</h2>\n<p>Structured data is one of the highest-impact SEO investments you can make. It enables rich results like review stars, recipe timers, FAQ dropdowns, and breadcrumb trails in search listings.</p>\n<h3 id=\"why-json-ld\">Why JSON-LD</h3>\n<p>Google recommends JSON-LD over microdata or RDFa. It is cleaner, easier to maintain, and does not clutter your HTML.</p>\n<h3 id=\"product-schema-example\">Product Schema Example</h3>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> Spatie\\SchemaOrg\\Schema</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">$productSchema </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> Schema</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">product</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">name</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Laravel SEO Toolkit'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">description</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Automated meta tags, sitemaps, and Lighthouse monitoring.'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">image</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">asset</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'images/product.png'</span><span style=\"color:#E1E4E8\">))</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    -></span><span style=\"color:#B392F0\">offers</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">Schema</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">offer</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        -></span><span style=\"color:#B392F0\">price</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">99</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        -></span><span style=\"color:#B392F0\">priceCurrency</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'USD'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        -></span><span style=\"color:#B392F0\">availability</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'https://schema.org/InStock'</span><span style=\"color:#E1E4E8\">)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    );</span></span></code></pre>\n<p>Then render it in Blade:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"blade\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">script</span><span style=\"color:#B392F0\"> type</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"application/ld+json\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    {!! $productSchema->toScript() !!}</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">script</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<p>Alternatively, if you are using ralphjsmit/laravel-seo, you can use the built-in <code>SchemaCollection</code> system described earlier.</p>\n<h3 id=\"faq-schema-with-ralphjsmitlaravel-seo\">FAQ Schema with ralphjsmit/laravel-seo</h3>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> RalphJSmit\\Laravel\\SEO\\SchemaCollection</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">public</span><span style=\"color:#F97583\"> function</span><span style=\"color:#B392F0\"> getDynamicSEOData</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> SEOData</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#F97583\"> new</span><span style=\"color:#79B8FF\"> SEOData</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        title</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">$this</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">title,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        schema</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">SchemaCollection</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">make</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">addFaqPage</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">function</span><span style=\"color:#E1E4E8\"> ($faqPage) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">            return</span><span style=\"color:#E1E4E8\"> $faqPage</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">                -></span><span style=\"color:#B392F0\">addQuestion</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">                    name</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'Does this package support Laravel 12?'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">                    acceptedAnswer</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'Yes, it fully supports Laravel 11, 12, and 13.'</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">                )</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">                -></span><span style=\"color:#B392F0\">addQuestion</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">                    name</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'Can I use it with Filament?'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">                    acceptedAnswer</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'Absolutely. There is a dedicated filament-seo companion package.'</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">                );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        }),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    );</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<p>After adding structured data, always validate it with <a href=\"https://search.google.com/test/rich-results\">Google’s Rich Results Test</a>.</p>\n<hr>\n<h2 id=\"6-performance--seo\">6. Performance + SEO</h2>\n<p>Google’s Core Web Vitals (LCP, FID/INP, CLS) are direct ranking signals. A fast site also improves user engagement metrics like bounce rate and time on page.</p>\n<h3 id=\"asset-preloading-with-romanzipplaravel-seo\">Asset Preloading with romanzipp/laravel-seo</h3>\n<p>One of the most unique features of <a href=\"https://romanzipp.github.io/Laravel-SEO/\">romanzipp/laravel-seo</a> is its ability to read the Laravel Mix manifest and automatically preload assets:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#B392F0\">seo</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">mix</span><span style=\"color:#E1E4E8\">();</span></span></code></pre>\n<p>This generates <code>&#x3C;link rel=\"preload\"></code> tags for your CSS and JavaScript bundles, telling the browser to fetch them early. The result is faster render times and better Lighthouse scores.</p>\n<h3 id=\"image-optimization\">Image Optimization</h3>\n<p>Every image should have descriptive <code>alt</code> text (accessibility and SEO win) and lazy loading:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"blade\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">img</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    src</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"</span><span style=\"color:#79B8FF\">{{</span><span style=\"color:#B392F0\"> asset</span><span style=\"color:#9ECBFF\">('storage/' </span><span style=\"color:#F97583\">.</span><span style=\"color:#E1E4E8\"> $post</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">image</span><span style=\"color:#9ECBFF\">) </span><span style=\"color:#79B8FF\">}}</span><span style=\"color:#9ECBFF\">\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    alt</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"</span><span style=\"color:#79B8FF\">{{</span><span style=\"color:#E1E4E8\"> $post</span><span style=\"color:#F97583\">-></span><span style=\"color:#E1E4E8\">title</span><span style=\"color:#79B8FF\"> }}</span><span style=\"color:#9ECBFF\"> — featured image\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    loading</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"lazy\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    width</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"1200\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    height</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"630\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<h3 id=\"response-caching\">Response Caching</h3>\n<p>For anonymous visitors, full-page caching eliminates database queries entirely:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"bash\"><code><span class=\"line\"><span style=\"color:#B392F0\">composer</span><span style=\"color:#9ECBFF\"> require</span><span style=\"color:#9ECBFF\"> spatie/laravel-responsecache</span></span></code></pre>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#6A737D\">// In a middleware or controller</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">use</span><span style=\"color:#79B8FF\"> Spatie\\ResponseCache\\Facades\\ResponseCache</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">ResponseCache</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">cacheIf</span><span style=\"color:#E1E4E8\">(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    auth</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">guest</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    $response,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    now</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">addHours</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">24</span><span style=\"color:#E1E4E8\">),</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    request</span><span style=\"color:#E1E4E8\">()</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">getRequestUri</span><span style=\"color:#E1E4E8\">()</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">);</span></span></code></pre>\n<h3 id=\"database-query-optimization\">Database Query Optimization</h3>\n<p>N+1 queries kill performance. Always eager-load relationships in your SEO-heavy pages:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"php\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Bad — N+1 queries</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">$posts </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> Post</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">all</span><span style=\"color:#E1E4E8\">(); </span><span style=\"color:#6A737D\">// Hits DB once, then once per post for SEO</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Good — eager load</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">$posts </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> Post</span><span style=\"color:#F97583\">::</span><span style=\"color:#B392F0\">with</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'seo'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'author'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'tags'</span><span style=\"color:#E1E4E8\">)</span><span style=\"color:#F97583\">-></span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">();</span></span></code></pre>\n<hr>\n<h2 id=\"7-monitoring--maintenance\">7. Monitoring &#x26; Maintenance</h2>\n<p>SEO is not a set-it-and-forget-it discipline. Regular monitoring is essential.</p>\n<h3 id=\"google-search-console\">Google Search Console</h3>\n<p>Connect your site to Google Search Console to monitor:</p>\n<ul>\n<li>Index coverage (which pages are indexed, which have errors)</li>\n<li>Search queries driving traffic</li>\n<li>Core Web Vitals reports</li>\n<li>Manual actions or security issues</li>\n</ul>\n<h3 id=\"lighthouse-ci\">Lighthouse CI</h3>\n<p>Integrate Lighthouse into your deployment pipeline:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"bash\"><code><span class=\"line\"><span style=\"color:#B392F0\">npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#79B8FF\"> -g</span><span style=\"color:#9ECBFF\"> @lhci/cli</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">lhci</span><span style=\"color:#9ECBFF\"> autorun</span><span style=\"color:#79B8FF\"> --collect.url=https://your-app.com</span><span style=\"color:#79B8FF\"> --upload.target=</span><span style=\"color:#9ECBFF\">\"temporary-public-storage\"</span></span></code></pre>\n<p>This catches SEO regressions (missing meta descriptions, low performance scores) before they reach production.</p>\n<h3 id=\"laravel-debugbar\">Laravel Debugbar</h3>\n<p>The <a href=\"https://github.com/barryvdh/laravel-debugbar\">Laravel Debugbar</a> package is excellent for inspecting meta tags during development — you can verify that the correct title, description, and OG tags are being generated for every route.</p>\n<h3 id=\"regular-seo-audits\">Regular SEO Audits</h3>\n<p>Set up a monthly checklist:</p>\n<ul>\n<li>Scan for duplicate or missing <code>&#x3C;title></code> tags</li>\n<li>Verify all pages have unique meta descriptions</li>\n<li>Check for broken internal links</li>\n<li>Validate structured data with Google’s Rich Results Test</li>\n<li>Monitor page speed and Core Web Vitals</li>\n<li>Review Search Console for index coverage issues</li>\n</ul>\n<hr>\n<h2 id=\"conclusion\">Conclusion</h2>\n<p>Here is the actionable takeaway:</p>\n<ol>\n<li><strong>Start with Laravel’s native features</strong> — clean routes, Blade sections for titles, response caching</li>\n<li><strong>Add a package</strong> — <a href=\"https://github.com/ralphjsmit/laravel-seo\">ralphjsmit/laravel-seo</a> is the best all-around choice for most projects. Install it, configure <code>config/seo.php</code>, add the <code>HasSEO</code> trait to your models, and render <code>{!! seo() !!}</code> in your layout.</li>\n<li><strong>Build an admin UI</strong> — use <a href=\"https://github.com/ralphjsmit/laravel-filament-seo\">ralphjsmit/laravel-filament-seo</a> or a custom form to let non-developers manage meta tags.</li>\n<li><strong>Add structured data</strong> — start with Article and BreadcrumbList schemas, then expand to Product, FAQ, or LocalBusiness as needed.</li>\n<li><strong>Monitor continuously</strong> — Google Search Console, Lighthouse CI, and regular audits keep your SEO healthy.</li>\n</ol>\n<p>What Laravel SEO tips do you use in your projects? Have you tried any of these packages? Drop a comment below or reach out on Twitter — we would love to hear what works for you.</p>\n<hr>\n<p>Found this guide helpful?</p>\n<p>Subscribe to our newsletter for more Laravel SEO tips and package updates.</p>";

